import math

def is_perfect_square(x):
    return int(math.sqrt(x))**2 == x

def find_good_permutation(n):
    if n == 1:
        return [0]

    # Check for small values of n
    if n <= 4:
        return [0, 1, 2, 3] if n % 2 == 0 else [0, 1, 3, 2]

    # For larger n, find a solution using backtracking
    def backtrack(i, current):
        if i == n:
            return current
        for j in range(n):
            if j not in current and is_perfect_square(i + j):
                return backtrack(i + 1, current + [j])

    return backtrack(0, [])

