def is_valid_painting(piles, colors, color_counts, max_diff):
    """
    Check if a painting with the given colors is valid for the given piles.

    :param piles: List of integers representing the number of pebbles in each pile.
    :param colors: Integer representing the number of colors available.
    :param color_counts: Dictionary mapping color to the number of pebbles of that color in each pile.
    :param max_diff: Integer representing the maximum allowed difference in color counts between piles.
    :return: Boolean indicating whether the painting is valid.
    """
    for color, count in color_counts.items():
        for i in range(len(piles) - 1):
            for j in range(i + 1, len(piles)):
                if abs(piles[i][color] - piles[j][color]) > max_diff:
                    return False
    return True

def paint_piles(piles, colors):
    """
    Paint the piles with the given colors to satisfy the conditions.

    :param piles: List of integers representing the number of pebbles in each pile.
    :param colors: Integer representing the number of colors available.
    :return: List of lists representing the painting of the piles.
    """
    if max(piles) - min(piles) > colors - 1:
        return "NO"

    color_counts = {}
    for pile in piles:
        for color in pile:
            if color in color_counts:
                color_counts[color] += pile.count(color)
            else:
                color_counts[color] = pile.count(color)

    max_diff = max(abs(max_count - min_count) for color, (max_count, min_count) in color_counts.items())
    if max_diff > colors - 1:
        return "NO"

    valid_paintings = []
    for i in range(1, colors + 1):
        painting = [i] * sum(pile.count(i) for pile in piles)
        valid_paintings.append(painting)

    return valid_paintings

