def king_moves(s, t):
    # Translate the starting and ending positions to a coordinate system
    s_x, s_y = ord(s[0]) - ord('a'), int(s[1]) - 1
    t_x, t_y = ord(t[0]) - ord('a'), int(t[1]) - 1

    # Calculate the minimum number of moves
    moves = abs(s_x - t_x) + abs(s_y - t_y)

    # Determine the direction of move
    if s_x < t_x:
        direction = 'R'
    elif s_x > t_x:
        direction = 'L'
    elif s_y < t_y:
        direction = 'U'
    elif s_y > t_y:
        direction = 'D'
    elif s_x == t_x:
        if s_y > t_y:
            direction = 'RD'
        else:
            direction = 'LU'
    else:
        if s_y > t_y:
            direction = 'RU'
        else:
            direction = 'LD'

    # Construct the moves
    moves_str = direction
    for _ in range(moves - 1):
        moves_str += direction
        if direction in ['R', 'L', 'U', 'D']:
            moves_str += direction
        elif direction == 'LU':
            moves_str += 'R'
        elif direction == 'LD':
            moves_str += 'L'
        elif direction == 'RU':
            moves_str += 'D'
        elif direction == 'RD':
            moves_str += 'U'

    # Print the moves
    print(moves)
    print(moves_str)

