import math
from collections import defaultdict

def mod_inverse(n, p):
    """Calculate the modular inverse of n under modulo p"""
    return pow(n, p-2, p)

def factorial(n, p):
    """Calculate the factorial modulo p"""
    if n == 0:
        return 1
    fact = 1
    for i in range(1, n+1):
        fact = (fact * i) % p
    return fact

def nCr(n, r, p):
    """Calculate the number of combinations (n choose r) modulo p"""
    fact_n = factorial(n, p)
    fact_r = factorial(r, p)
    fact_n_r = factorial(n-r, p)
    total = (fact_n * mod_inverse(fact_r, p)) % p
    return (total * mod_inverse(fact_n_r, p)) % p

def lcm(a, b):
    """Calculate the least common multiple of a and b"""
    return a * b // math.gcd(a, b)

