from collections import Counter

def restore_numbers(divisors):
    divisor_count = Counter(divisors)
    common_divisors = []

    for divisor, count in divisor_count.items():
        if count == 2:
            common_divisors.extend([divisor] * 2)

    x = 1
    y = 1
    for divisor in common_divisors:
        if divisor_count[divisor] == 1:
            if divisor > 1:
                x *= divisor
            else:
                y *= divisor

    return [x, y]

