class ColonyTravel:
    def __init__(self, N, M):
        self.N = N
        self.M = M
        self.roads = [[] for _ in range(N)]
        self.costs = [None] * N

    def add_road(self, X, Y, cost):
        self.roads[X-1].append((Y-1, cost))
        self.roads[Y-1].append((X-1, cost))
        self.costs[X-1] = cost
        self.costs[Y-1] = cost

    def find_max_playtime(self, A, K):
        visited = [False] * self.N
        visited[A-1] = True
        total_time = 0
        road_count = 0

        while K > 0:
            for i in range(self.N):
                if not visited[i] and (self.costs[i] == None or self.costs[i] <= K):
                    total_time += self.costs[i]
                    K -= self.costs[i]
                    visited[i] = True
                    break
            if total_time > K:
                return 0
            elif total_time == K:
                return total_time
            road_count += 1

        return total_time + self.roads[A-1].count((A-1, total_time + self.roads[A-1].count((A-1, total_time) + 1)))

    def query(self, A, K):
        return self.find_max_playtime(A, K)


