def interpreter(tape):
    data = [0]
    selector = 0
    output = []

    for char in tape:
        if char == '>':
            selector = (selector + 1) % len(data)
        elif char == '<':
            selector = (selector - 1) % len(data)
        elif char == '*':
            output.append(chr(data[selector] + 32))
        elif char == '+':
            data[selector] = (data[selector] + 1) % 256
        elif char == '-':
            data[selector] = (data[selector] - 1) % 256
        elif char == '/':
            data[selector] = 0
        elif char == '!':
            data.append(0)
        elif char == '*':
            output.append(char)
        elif char == '+':
            data.append(chr(data[selector] + 32))
        elif char == '-':
            data.append(chr(data[selector] - 32))
        elif char == '/':
            data.append(0)
        elif char == '!':
            data.append('*')

    return ''.join(output)
