def calculate_max_damage(n, k, damage, hits):
    dp = [0] * (n + 1)
    dp[1] = damage[0]

    for i in range(1, n):
        dp[i + 1] = max(dp[i] + damage[i], damage[i])

    max_damage = dp[n]
    max_index = n

    for i in range(n - 1, -1, -1):
        if dp[i] == max_damage:
            max_index = i
            break

    if max_index < n - k:
        return max_damage
    else:
        return max_damage - damage[max_index] + dp[n]

