def find_path(matrix, start, end):
    rows = len(matrix)
    cols = len(matrix[0])
    path = []
    visited = [[False] * cols for _ in range(rows)]
    x, y = start
    stack = [(x, y)]

    while stack:
        x, y = stack.pop()
        if (x, y) == end:
            break
        if not visited[x][y]:
            visited[x][y] = True
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and matrix[nx][ny] != 'T':
                    path.append((nx, ny))
                    stack.append((nx, ny))

    return path

def min_steps(matrix):
    rows, cols = len(matrix), len(matrix[0])
    start = None
    end = None

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 'S':
                start = (i, j)
            elif matrix[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    path = find_path(matrix, start, end)
    steps = len(path)

    return steps

# Example usage
matrix = [
    'S P P P P',
    'T P T P P',
    'T P P P P',
    'P T E T T',
    'P T P T T'
]

print(min_steps(matrix))  # Output: 5
