from collections import defaultdict

def xor_tree(n, edges, init, goal):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    cumulative_xor = [0] * n
    cumulative_xor[0] = init[0]
    for i in range(1, n):
        cumulative_xor[i] = cumulative_xor[i-1] ^ goal[i]

    def xor_in_range(node, start, end):
        xor_tree = node
        for i in range(start, end+1):
            xor_tree ^= cumulative_xor[node]
            node = graph[node][xor_tree.bit_count(xor_tree) - 1]
        return node

    def flip_node(node):
        nonlocal cumulative_xor
        cumulative_xor[node] ^= 1
        for child in graph[node]:
            cumulative_xor[child] ^= 1

    min_operations = 0
    for node in range(n):
        if goal[node] != cumulative_xor[node]:
            min_operations += 1
            flip_node(node)

    return min_operations, [node+1 for node in range(min_operations)]
```

