import math

def logistic_map(width, height, xs, ys):
    if not xs or not ys:
        return [[None for _ in range(width)] for _ in range(height)]

    grid = [[math.inf for _ in range(width)] for _ in range(height)]
    for x, y in zip(xs, ys):
        grid[y][x] = 0

    for y in range(height):
        for x in range(width):
            if grid[y][x] == math.inf:
                min_distance = math.inf
                for x_supply, y_supply in zip(xs, ys):
                    distance = abs(x_supply - x) + abs(y_supply - y)
                    if distance < min_distance:
                        min_distance = distance

                grid[y][x] = min_distance

    return grid
