def find_shortest_substring_with_all_chars(s):
    char_count = {'1': 0, '2': 0, '3': 0}
    left = 0
    min_length = float('inf')
    max_length = 0
    left_char_count = {'1': 0, '2': 0, '3': 0}
    for right in range(len(s)):
        char_count[s[right]] += 1
        if s[right] not in left_char_count:
            left_char_count[s[right]] = right
        max_length = max(max_length, right - left + 1)
        if all(count == len(s) or count == 0 for count in char_count.values()):
            min_length = min(min_length, max_length - (right - left_char_count[s[right]]))
            left_char_count[s[left]] -= 1
            left += 1
    return min_length if min_length != float('inf') else 0

