from math import gcd

def uniform_random(lower, upper):
    """Generate a uniform random number between lower and upper."""
    return lower + (upper - lower) * random.random()

def probability(x, y, C):
    """Calculate the probability that x + y < C."""
    count = 0
    for i in range(1, C + 1):
        if uniform_random(0, x) + uniform_random(0, y) < i:
            count += 1
    return count / (C * (C + 1) / 2)

