def identify_name_letters(guest_name, host_name, found_letters):
    guest_count = {}
    host_count = {}

    # Count the occurrences of each letter in the guest's name
    for letter in guest_name:
        guest_count[letter] = guest_count.get(letter, 0) + 1

    # Count the occurrences of each letter in the host's name
    for letter in host_name:
        host_count[letter] = host_count.get(letter, 0) + 1

    # Count the occurrences of each letter in the found letters
    found_count = {}
    for letter in found_letters:
        found_count[letter] = found_count.get(letter, 0) + 1

    # Compare the counts to see if the found letters can form the names
    for letter, count in guest_count.items():
        if letter not in found_count or found_count[letter] != count:
            return "NO"
    for letter, count in host_count.items():
        if letter not in found_count or found_count[letter] != count:
            return "NO"

    return "YES"

