def lcm(x, y):
    return x * y // math.gcd(x, y)

def find_max_lcm_permutation(n):
    max_sum = -1
    best_permutation = []
    all_permutations = permutations(range(1, n + 1))

    for perm in all_permutations:
        current_sum = sum(lcm(i, perm[i-1]) for i in range(1, n + 1))
        if current_sum > max_sum:
            max_sum = current_sum
            best_permutation = perm

    return list(best_permutation)

