def find_abc_sumsqcube(c_max, num_sol):
    valid_c = []
    for c in range(2, c_max + 1):
        if c % 2 == 0:
            continue
        count = 0
        for a in range(1, c):
            for b in range(a, c):
                if a**2 + b**2 == c**3:
                    count += 1
                    if count == num_sol:
                        valid_c.append(c)
                        break
        if count >= num_sol:
            break
    return sorted(valid_c)

