from collections import defaultdict

def can_transform_to_a(n, q, operations):
    operations.sort(key=lambda x: len(x[0]))
    suffixes = defaultdict(list)
    for a, b in operations:
        suffixes[b].append(a)

    def can_transform_to_a_helper(n, operations):
        if n == 1:
            return 1
        if n == 2:
            return 2
        if n == 3:
            return 4

        count = 0
        for a in operations[0]:
            new_n = n - 2
            if new_n in suffixes[a]:
                count += can_transform_to_a_helper(new_n, operations[1:])
        return count

    return can_transform_to_a_helper(n, operations)

