def min_groups(n, manager):
    # Initialize the tree as a list of lists, where each list represents an employee with their immediate manager
    tree = [[] for _ in range(n)]
    for i in range(n):
        if manager[i] != -1:
            tree[manager[i]].append(i)

    # Depth-first search to find the maximum depth in the tree
    def dfs(node, parent):
        depth = 0
        for child in tree[node]:
            if child != parent:
                depth = max(dfs(child, node) + 1, depth)
        return depth

    # Find the maximum depth in the tree
    max_depth = 0
    for i in range(n):
        if tree[i]:
            max_depth = max(dfs(i, -1), max_depth)

    # The number of groups needed is the sum of the maximum depth and one (for the root node)
    return max_depth + 1
```

