def on_line(points):
    if not points or len(points) == 1:
        return True
    x_coords = [p[0] for p in points]
    y_coords = [p[1] for p in points]

    if x_coords[1] - x_coords[0] == 0 or y_coords[1] - y_coords[0] == 0:
        return False

    slope = (y_coords[1] - y_coords[0]) / (x_coords[1] - x_coords[0])

    for i in range(2, len(points)):
        if (points[i][1] - points[0][1]) / (points[i][0] - points[0][0]) != slope:
            return False

    return True
